package com.example.starter.forwarder;

import java.time.LocalDateTime;

/**
 * 持久化消息行的只读视图。
 */
public record MessageView(
        long id,
        String deviceId,
        String topic,
        long deviceSeq,
        int priority,
        String dedupKey,
        String payload,
        MessageStatus status,
        int attemptCount,
        LocalDateTime inFlightSince,
        LocalDateTime createdAt,
        LocalDateTime updatedAt) {
}

package com.example.starter.forwarder;

/**
 * 消息入库结果。
 */
public enum IngestOutcome {
    /** 已入队（在线时会立即尝试转发）。 */
    QUEUED,
    /** 相同 dedupKey 已存在，幂等忽略。 */
    DUPLICATE,
    /** 离线且 Topic 策略为 DROP，已丢弃并写审计。 */
    DROPPED_BY_POLICY,
    /** 容量不足且无可驱逐记录，已拒绝并写审计。 */
    REJECTED_CAPACITY
}

package com.example.starter.forwarder;

/**
 * ACK 处理结果。重复 ACK 不得改变计数。
 */
public enum AckOutcome {
    /** 首次确认，消息不再转发。 */
    ACKED,
    /** 重复 ACK，状态与计数不变。 */
    DUPLICATE,
    /** 未找到对应消息。 */
    NOT_FOUND
}

