        assertTrue(messages.findByDedupKey("k3").isEmpty());
        List<AuditRepository.AuditRow> rejects = audit.findByType(AuditEventType.REJECTED_CAPACITY);
        assertEquals(1, rejects.size());
        assertEquals("k3", rejects.get(0).dedupKey());
    }
}

